import { call, put } from 'redux-saga/effects';
import makeRequest from '../../commom/makeRequest';
import { GET_ALL_PRODUCTS_SUCCESS, GET_ALL_PRODUCTS_FAIL } from '../actions/types';
export default function*(action) {
  try {
    const res = yield call(makeRequest, action.payload.config);
    yield put({ type: GET_ALL_PRODUCTS_SUCCESS, payload: res.data});
  } catch (error) {
    yield put({ type: GET_ALL_PRODUCTS_FAIL, payload: error.message });
  }
}
